def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    seen = set()
    tiles = []

    # Find each contiguous nonzero framed tile, including tiles clipped by an edge.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)

            # The perimeter is the frame; a side at the grid edge may be clipped.
            ir0 = r0 + (r0 > 0)
            ir1 = r1 + 1 - (r1 < h - 1)
            ic0 = c0 + (c0 > 0)
            ic1 = c1 + 1 - (c1 < w - 1)
            if ir0 >= ir1 or ic0 >= ic1:
                continue

            interior = [grid[x][y]
                        for x in range(ir0, ir1)
                        for y in range(ic0, ic1)]
            color = Counter(interior).most_common(1)[0][0]
            tiles.append((ir0, ir1, ic0, ic1, color))

    if not tiles:
        return [row[:] for row in grid]

    common = Counter(t[4] for t in tiles).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for i, a in enumerate(tiles):
        ar0, ar1, ac0, ac1, color = a
        if color == common:
            continue
        for b in tiles[i + 1:]:
            br0, br1, bc0, bc1, bcolor = b
            if bcolor != color:
                continue

            # Connect matching tiles in the same tile row.
            if (ar0, ar1) == (br0, br1) and ac1 <= bc0:
                for r in range(ar0, ar1):
                    for c in range(ac1, bc0):
                        if out[r][c] == 0:
                            out[r][c] = color
            elif (ar0, ar1) == (br0, br1) and bc1 <= ac0:
                for r in range(ar0, ar1):
                    for c in range(bc1, ac0):
                        if out[r][c] == 0:
                            out[r][c] = color

            # Connect matching tiles in the same tile column.
            if (ac0, ac1) == (bc0, bc1) and ar1 <= br0:
                for r in range(ar1, br0):
                    for c in range(ac0, ac1):
                        if out[r][c] == 0:
                            out[r][c] = color
            elif (ac0, ac1) == (bc0, bc1) and br1 <= ar0:
                for r in range(br1, ar0):
                    for c in range(ac0, ac1):
                        if out[r][c] == 0:
                            out[r][c] = color

    return out
